          "stepId": "reduce-pan-juices",
          "name": "Reduce pan juices with stock and mustard",
          "task": "burner",
          "duration": { "type": "fixed", "seconds": 360 },
          "startTrigger": { "type": "afterStep", "stepId": "roast-chicken-and-potatoes", "instances": "all" }
        },
        {
          "stepId": "whisk-in-butter",
          "name": "Whisk in cold butter",
          "task": "prep",
          "duration": { "type": "fixed", "seconds": 120 },
          "startTrigger": { "type": "afterStep", "stepId": "reduce-pan-juices" }
        }
      ]
    },
    {
      "trackId": "salad",
      "name": "Salad Prep",
      "steps": [
        {
          "stepId": "wash-and-dry-leaves",
          "name": "Wash and dry salad leaves",
          "task": "prep",
          "duration": { "type": "fixed", "seconds": 360 },
          "startTrigger": { "type": "afterStep", "stepId": "prep-chicken" }
        },
        {
          "stepId": "prepare-vinaigrette",
          "name": "Shake vinaigrette",
          "task": "prep",
          "duration": { "type": "fixed", "seconds": 180 },
          "startTrigger": { "type": "afterStep", "stepId": "wash-and-dry-leaves" }
        },
        {
          "stepId": "dress-salad",
          "name": "Dress salad",
          "task": "prep",
          "duration": { "type": "fixed", "seconds": 120 },
          "startTrigger": { "type": "afterStep", "stepId": "rest-chicken", "offsetSeconds": -180 }
        }
      ]
    },
    {
      "trackId": "serve",
      "name": "Serve",
      "steps": [
        {
          "stepId": "slice-and-plate",
          "name": "Slice chicken and plate",
          "task": "prep",
          "duration": { "type": "fixed", "seconds": 360 },
          "startTrigger": { "type": "afterStep", "stepId": "rest-chicken" }
        }
      ]
    }
  ],
  "resourceConstraints": [
    { "task": "oven", "maxConcurrent": 1 },
    { "task": "prep", "maxConcurrent": 1 },
    { "task": "burner", "maxConcurrent": 1 },
    { "task": "sheet-pan", "maxConcurrent": 2 }
  ],
  "metadata": { "serves": "4" }
}
```

